//write a function that takes a string and return  how many times each character appears in the string
function countCharacters(str) {
    const charCount = {};

    for (let char of str) {
        if (charCount[char]) {
            charCount[char]++;
        } else {
            charCount[char] = 1;
        }
    }

    return charCount;
}

//write a function that checks if two strings are anagrams
function areAnagrams(str1, str2) {
    const count1 = countCharacters(str1);
    const count2 = countCharacters(str2);

    if (Object.keys(count1).length !== Object.keys(count2).length) {
        return false;
    }

    for (let char in count1) {
        if (count1[char] !== count2[char]) {
            return false;
        }
    }

    return true;
}




